import json, glob

# Let's inspect all tool outputs saved in tool-outputs directory to collect all Linear issues
files = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/mcp_mcp88585683_list_issues*.txt', recursive=True)

all_issues = {}
for f in files:
    with open(f) as fn:
        content = fn.read()
        # content contains wrapper text or raw json
        try:
            # find json starting with {\"issues\": or {\"output\":
            start = content.find('{\"issues\":')
            if start == -1:
                start = content.find('{\"output\":')
            if start != -1:
                data = json.loads(content[start:])
                if 'output' in data:
                    data = json.loads(data['output'])
                for issue in data.get('issues', []):
                    all_issues[issue['id']] = issue
        except Exception as e:
            pass

print(f'Total unique issues collected from tool outputs: {len(all_issues)}')
for id, issue in sorted(all_issues.items()):
    title = issue['title']
    state = issue['state']['name']
    assignee = issue['assignee']['displayName'] if issue.get('assignee') else 'Unassigned'
    print(f'{id}: [{state}] (Assignee: {assignee}) - {title}')
