import json, glob

files = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/*.txt', recursive=True)

clusters = {'south': [], 'north': [], 'east': [], 'west': []}

for f in files:
    with open(f) as fn:
        content = fn.read()
        try:
            start = content.find('{\"issues\":')
            if start == -1: start = content.find('{\"output\":')
            if start != -1:
                data = json.loads(content[start:])
                if 'output' in data: data = json.loads(data['output'])
                for issue in data.get('issues', []):
                    text = (issue['title'] + ' ' + issue.get('description', '')).lower()
                    for c in clusters:
                        if c in text and ('cluster' in text or 'hvac' in text or 'preventive' in text or 'panel' in text or 'plumbing' in text or 'spot-check' in text):
                            if issue['id'] not in [x['id'] for x in clusters[c]]:
                                clusters[c].append(issue)
        except Exception as e: pass

for c, issue_list in clusters.items():
    print(f'==================== {c.upper()} CLUSTER ({len(issue_list)} issues) ====================')
    for issue in sorted(issue_list, key=lambda x: int(x['id'].split('-')[1])):
        assignee = issue.get('assignee', {}).get('displayName', 'Unassigned') if issue.get('assignee') else 'Unassigned'
        print(f\"{issue['id']} | [{issue['state']['name']}] | Assignee: {assignee} | Title: {issue['title']}\")
        print(f\"   Desc: {issue.get('description')}\")
